export function Background({
  type = "{{type}}",
  color1 = "{{color1}}",
  color2 = "{{color2}}",
  height = {{height}},
}) {
  const bg = type === "solid" ? color1
    : type === "gradient" ? `linear-gradient(135deg, ${color1}, ${color2})`
    : `radial-gradient(${color2} 2.5px, transparent 2.5px)`;
  const style = { height, borderRadius: 10, border: "1.5px solid #24143022",
    ...(type === "dots" ? { backgroundColor: color1, backgroundImage: bg, backgroundSize: "16px 16px" } : { background: bg }) };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A panel demonstrating a solid colour, a two-colour gradient, or a dot pattern as its background">
      <div style={style} />
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>background: {type} &middot; {color1} &amp; {color2}</p>
    </div>
  );
}
